import{_ as n,o as a,c as s,e}from"./app-6be1f847.js";const t="/vuepress_blog/assets/java_modifier-ed330264.png",o={},p=e(`<h3 id="new-integer-123-与-integer-valueof-123-的区别" tabindex="-1"><a class="header-anchor" href="#new-integer-123-与-integer-valueof-123-的区别" aria-hidden="true">#</a> <code>new Integer(123)</code> 与 <code>Integer.valueOf(123)</code> 的区别</h3><p><code>new Integer(123)</code> 每次都会新建一个对象，<code>Integer.valueOf(123)</code> 会使用缓存池中的对象，多次调用会取得同一个对象的引用。</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token class-name">Integer</span> x <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Integer</span><span class="token punctuation">(</span><span class="token number">123</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token class-name">Integer</span> y <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Integer</span><span class="token punctuation">(</span><span class="token number">123</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span>x <span class="token operator">==</span> y<span class="token punctuation">)</span><span class="token punctuation">;</span>    <span class="token comment">// false</span>
<span class="token class-name">Integer</span> z <span class="token operator">=</span> <span class="token class-name">Integer</span><span class="token punctuation">.</span><span class="token function">valueOf</span><span class="token punctuation">(</span><span class="token number">123</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token class-name">Integer</span> k <span class="token operator">=</span> <span class="token class-name">Integer</span><span class="token punctuation">.</span><span class="token function">valueOf</span><span class="token punctuation">(</span><span class="token number">123</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span>z <span class="token operator">==</span> k<span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// true</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>基本类型对应的缓冲池如下:</p><ul><li>boolean values true and false</li><li>all byte values</li><li>short values between -128 and 127</li><li>int values between -128 and 127</li><li>char in the range <code>\\u0000</code> to <code>\\u007F</code></li></ul><h3 id="string" tabindex="-1"><a class="header-anchor" href="#string" aria-hidden="true">#</a> String</h3><p><code>String</code> 被声明为 <strong>final</strong>，因此它不可被继承。内部使用 char 数组存储数据，该数组被声明为 final，这意味着 value 数组初始化之后就不能再引用其它数组。并且 String 内部没有改变 value 数组的方法，因此可以保证 String 不可变。</p><p><strong>不可变的好处</strong></p><ul><li><ol><li>可以缓存 hash 值因为 String 的 hash 值经常被使用，例如 String 用做 HashMap 的 key。不可变的特性可以使得 hash 值也不可变，因此只需要进行一次计算。</li></ol></li><li><ol start="3"><li>String Pool 的需要 。如果一个 String 对象已经被创建过了，那么就会从 String Pool 中取得引用。只有 String 是不可变的，才可能使用 String Pool。</li></ol></li><li><ol start="3"><li>安全性String 经常作为参数，String 不可变性可以保证参数不可变。例如在作为网络连接参数的情况下如果 String 是可变的，那么在网络连接过程中，String 被改变，改变 String 对象的那一方以为现在连接的是其它主机，而实际情况却不一定是。</li></ol></li><li><ol start="4"><li>线程安全String 不可变性天生具备线程安全，可以在多个线程中安全地使用。</li></ol></li></ul><p><strong>可变性</strong></p><ol><li>可变性 String 不可变; StringBuffer 和 StringBuilder 可变.</li><li>线程安全 String 不可变，因此是线程安全的; StringBuilder 不是线程安全的; StringBuffer 是线程安全的，内部使用 <strong>synchronized</strong> 进行同步</li></ol><h4 id="new-string-vs-双引号字符串" tabindex="-1"><a class="header-anchor" href="#new-string-vs-双引号字符串" aria-hidden="true">#</a> new String vs 双引号字符串</h4><ul><li>当创建字符串时（如 <code>String s = &quot;abc&quot;</code>），JVM 会先检查常量池：如果已有 &quot;abc&quot;，直接返回常量池中的引用；如果没有，就把 &quot;abc&quot; 放入常量池并返回引用。</li><li>而通过 <code>new String(&quot;abc&quot;)</code> 创建字符串时，会在堆内存中创建一个新对象，同时常量池也会存入 &quot;abc&quot;（如果没有的话），此时 <code>new String(&quot;abc&quot;)</code> 返回的是堆对象的引用，而非常量池引用。</li></ul><h4 id="string-intern-方法的作用" tabindex="-1"><a class="header-anchor" href="#string-intern-方法的作用" aria-hidden="true">#</a> <code>String.intern()</code> 方法的作用</h4><p><code>intern()</code> 是 String 类的一个本地方法（native method），核心作用是：</p><ul><li>如果常量池中已经存在当前字符串的等值字符串（通过 <code>equals()</code> 判断），则返回常量池中的该字符串引用；</li><li>如果常量池中不存在，则将当前字符串的引用（JDK 7+）或副本（JDK 6 及以前）放入常量池，并返回该引用。</li><li>== 比较的是引用地址，equals() 比较的是字符串内容； 经过 <code>intern()</code> 后，等值的字符串引用地址一致，== 才会返回 <code>true</code>。</li></ul><p>简单说：<code>intern()</code> 能让堆中的字符串对象 “关联” 到常量池，实现引用复用，节省内存；适用场景是大量重复字符串的场景，避免滥用导致常量池膨胀</p><h3 id="jdk8-内存模型" tabindex="-1"><a class="header-anchor" href="#jdk8-内存模型" aria-hidden="true">#</a> jdk8 内存模型</h3><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token constant">JVM</span> 内存
├── 堆（Heap）：新生代 <span class="token operator">+</span> 老年代 <span class="token operator">+</span> 字符串常量池
├── 方法区（Metaspace 实现，本地内存）：类元数据 <span class="token operator">+</span> 运行时常量池 <span class="token operator">+</span> 静态变量
├── 虚拟机栈（线程私有）
├── 本地方法栈（线程私有）
└── 程序计数器（线程私有）
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="float-与-double" tabindex="-1"><a class="header-anchor" href="#float-与-double" aria-hidden="true">#</a> <code>float</code> 与 <code>double</code></h3><p><code>1.1</code> 字面量属于 <strong>double</strong> 类型，不能直接将 <code>1.1</code> 直接赋值给 <strong>float</strong> 变量，因为这是向下转型。Java 不能隐式执行向下转型，因为这会使得<strong>精度降低</strong>。</p><p><code>1.1f</code> 字面量才是 <strong>float</strong> 类型。</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token keyword">float</span> f <span class="token operator">=</span> <span class="token number">1.1f</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h3 id="java-访问权限修饰符" tabindex="-1"><a class="header-anchor" href="#java-访问权限修饰符" aria-hidden="true">#</a> Java 访问权限修饰符</h3><p><img src="`+t+`" alt="java修饰符关键字"></p><h3 id="equals-与" tabindex="-1"><a class="header-anchor" href="#equals-与" aria-hidden="true">#</a> <code>equals()</code> 与 <code>==</code></h3><ul><li>对于基本类型，== 判断两个值是否相等，基本类型没有 equals() 方法。</li><li>对于引用类型，== 判断两个变量是否引用同一个对象，而 equals() 判断引用的对象是否等价。</li></ul><p>覆写 equals 方法</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">EqualExample</span> <span class="token punctuation">{</span>
    <span class="token keyword">private</span> <span class="token keyword">int</span> x<span class="token punctuation">;</span>
    <span class="token keyword">private</span> <span class="token keyword">int</span> y<span class="token punctuation">;</span>
    <span class="token keyword">private</span> <span class="token keyword">int</span> z<span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token class-name">EqualExample</span><span class="token punctuation">(</span><span class="token keyword">int</span> x<span class="token punctuation">,</span> <span class="token keyword">int</span> y<span class="token punctuation">,</span> <span class="token keyword">int</span> z<span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">this</span><span class="token punctuation">.</span>x <span class="token operator">=</span> x<span class="token punctuation">;</span>
        <span class="token keyword">this</span><span class="token punctuation">.</span>y <span class="token operator">=</span> y<span class="token punctuation">;</span>
        <span class="token keyword">this</span><span class="token punctuation">.</span>z <span class="token operator">=</span> z<span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token annotation punctuation">@Override</span>
    <span class="token keyword">public</span> <span class="token keyword">boolean</span> <span class="token function">equals</span><span class="token punctuation">(</span><span class="token class-name">Object</span> o<span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token keyword">this</span> <span class="token operator">==</span> o<span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token boolean">true</span><span class="token punctuation">;</span>
        <span class="token keyword">if</span> <span class="token punctuation">(</span>o <span class="token operator">==</span> <span class="token keyword">null</span> <span class="token operator">||</span> <span class="token function">getClass</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">!=</span> o<span class="token punctuation">.</span><span class="token function">getClass</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token boolean">false</span><span class="token punctuation">;</span>

        <span class="token class-name">EqualExample</span> that <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token class-name">EqualExample</span><span class="token punctuation">)</span> o<span class="token punctuation">;</span>

        <span class="token keyword">if</span> <span class="token punctuation">(</span>x <span class="token operator">!=</span> that<span class="token punctuation">.</span>x<span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token boolean">false</span><span class="token punctuation">;</span>
        <span class="token keyword">if</span> <span class="token punctuation">(</span>y <span class="token operator">!=</span> that<span class="token punctuation">.</span>y<span class="token punctuation">)</span> <span class="token keyword">return</span> <span class="token boolean">false</span><span class="token punctuation">;</span>
        <span class="token keyword">return</span> z <span class="token operator">==</span> that<span class="token punctuation">.</span>z<span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="java-类初始化顺序" tabindex="-1"><a class="header-anchor" href="#java-类初始化顺序" aria-hidden="true">#</a> java 类初始化顺序</h3><p>存在继承的情况下，初始化顺序为</p><ul><li>父类(静态变量、静态语句块)</li><li>子类(静态变量、静态语句块)</li><li>父类(实例变量、普通语句块)</li><li>父类(构造函数)</li><li>子类(实例变量、普通语句块)</li><li>子类(构造函数)</li></ul><h3 id="反射" tabindex="-1"><a class="header-anchor" href="#反射" aria-hidden="true">#</a> 反射</h3><p>每个类都有一个 Class 对象，包含了与类有关的信息。当编译一个新类时，会产生一个同名的 <strong>.class</strong> 文件，该文件内容保存着 Class 对象。类加载相当于 Class 对象的加载。类在第一次使用时才动态加载到 JVM 中，可以使用 <code>Class.forName(&quot;com.mysql.jdbc.Driver&quot;)</code> 这种方式来控制类的加载，该方法会返回一个 Class 对象。反射可以提供运行时的类信息，并且这个类可以在运行时才加载进来，甚至在编译时期该类的 .class 不存在也可以加载进来。</p><p><strong>Class 和 java.lang.reflect</strong> 一起对反射提供了支持，java.lang.reflect 类库主要包含了以下三个类:</p><ul><li>Field : 可以使用 get() 和 set() 方法读取和修改 Field 对象关联的字段；</li><li>Method : 可以使用 invoke() 方法调用与 Method 对象关联的方法；</li><li>Constructor : 可以用 Constructor 创建新的对象</li></ul><h3 id="异常" tabindex="-1"><a class="header-anchor" href="#异常" aria-hidden="true">#</a> 异常</h3><p><strong>Throwable</strong> 可以用来表示任何可以作为异常抛出的类，分为两种: Error 和 Exception。 其中 Error 用来表示 JVM 无法处理的错误，Exception 分为两种:</p><ul><li>受检异常 : 需要用 try...catch... 语句捕获并进行处理，并且可以从异常中恢复；</li><li>非受检异常 : 是程序运行时错误，例如除 0 会引发 Arithmetic Exception，此时程序崩溃并且无法恢复。</li></ul>`,39),l=[p];function c(i,r){return a(),s("div",null,l)}const d=n(o,[["render",c],["__file","/home/runner/work/vuepress_blog/vuepress_blog/docs/.vuepress/.temp/pages/java/java_basic.html.vue"]]);export{d as default};
